actions.script:
const context = ec.context.get('manufacturing') || {}
const plant = plantId || context.plantId || null
const span = Math.max(1, Math.min(92, Number(days) || 14))
// the days from fromDay (today), in the user's zone
const first = /^\d{4}-\d{2}-\d{2}$/.test(String(fromDay || '')) ? String(fromDay) : ec.l10n.format(ec.user.nowTimestamp, 'yyyy-MM-dd')
const [y, m, d] = first.split('-').map(Number)
const last = new Date(Date.UTC(y, m - 1, d + span)).toISOString().slice(0, 10)
const dayStart = (day) => ec.l10n.parseTimestamp(day + ' 00:00:00.000', 'yyyy-MM-dd HH:mm:ss.SSS')
if (plant) ec.service.sync().name('ironstone.manufacturing.AccessServices.check#Record').requireNewTransaction(true).parameters({recordType: 'facility', recordId: plant}).call()
if (ec.message.hasError()) { ec.message.clearErrors(); ec.web.sendJsonResponse({notAvailable: true}); return }
const parameters = {plantFacilityId: plant, scheduleChangeId: scheduleChangeId || null, fromDate: dayStart(first), thruDate: dayStart(last)}
const out = ec.service.sync().name('mantle.work.ProductionPlanningServices.get#ProductionSchedule').requireNewTransaction(true).parameters(parameters).call() || {}
if (ec.message.hasError()) { const message = ec.message.getErrorsString(); ec.message.clearErrors(); ec.web.sendJsonResponse({failed: message}); return }
const web = context.webBase || '/qapps/Manufacturing'
const opUrl = (row) => web + '/WorkOrders/WorkOrderDetail/Operations?workEffortId=' + encodeURIComponent(row.runWorkEffortId)
    + '&selectedOperationId=' + encodeURIComponent(row.workEffortId)
for (const row of Array.from(out.operationList || []).concat(Array.from(out.unscheduledList || []))) { row.url = opUrl(row) }
const caps = context.capabilities || {}
const plants = Array.from(ec.service.sync().name('ironstone.manufacturing.AccessServices.get#Choices').parameters({choice: 'plants'}).call()?.options || [])
ec.message.clearErrors()
ec.web.sendJsonResponse({schedule: Object.assign({}, out, {canSchedule: !!out.canSchedule && !!caps.schedule,
    canOverride: !!out.canOverride && !!caps.supervise}), plantId: plant, plantOptions: plants, days: span,
    snapshotUrl: web + '/Planning/ScheduleSnapshot?renderMode=html-print&lastStandalone=true&plantId=' + encodeURIComponent(plant || '')
        + '&fromDay=' + encodeURIComponent(fromDay || '') + '&days=' + span})

const action = ['preview', 'apply', 'unschedule', 'request'].includes(moveAction) ? moveAction : 'preview'
ec.service.sync().name('ironstone.manufacturing.AccessServices.check#Record').requireNewTransaction(true).parameters({recordType: 'operation',
    recordId: operationWorkEffortId || '', capability: action === 'preview' ? null : 'schedule'}).call()
let out = {}
if (!ec.message.hasError()) out = ec.service.sync().name('mantle.work.ProductionPlanningServices.schedule#ProductionOperation').requireNewTransaction(true).parameters({
    action, workEffortId: operationWorkEffortId || '', facilityId: targetFacilityId || null, startDate: startText || null,
    endDate: endText || null, reason: reason || null, override: override === 'Y' || override === 'true',
    expectedRevision: expectedRevision ?? null, expectedRunRevision: expectedRunRevision ?? null,
    operationKey: action === 'preview' ? null : (operationKey || null)}).call() || {}
if (ec.message.hasError()) { const message = ec.message.getErrorsString(); ec.message.clearErrors()
    ec.web.sendJsonResponse({failed: true, messageInfos: [{type: 'danger', message}]}); return }
const result = out.result || {}
ec.web.sendJsonResponse(action === 'preview' ? {preview: result}
    : {result, messageInfos: [{type: result.resultCode === 'REQUESTED' ? 'info' : 'success', message: result.message}]})

ec.service.sync().name('ironstone.manufacturing.AccessServices.check#Record').requireNewTransaction(true).parameters({recordType: 'scheduleChange',
    recordId: scheduleChangeId || '', capability: 'supervise'}).call()
let out = {}
if (!ec.message.hasError()) out = ec.service.sync().name('mantle.work.ProductionPlanningServices.schedule#ProductionOperation').requireNewTransaction(true).parameters({
    action: decision === 'approve' ? 'approve' : 'refuse', scheduleChangeId: scheduleChangeId || '', reason: reason || null,
    operationKey: operationKey || null}).call() || {}
if (ec.message.hasError()) { const message = ec.message.getErrorsString(); ec.message.clearErrors()
    ec.web.sendJsonResponse({failed: true, messageInfos: [{type: 'danger', message}]}); return }
ec.web.sendJsonResponse({result: out.result || {}, messageInfos: [{type: 'success', message: out.result?.message}]})

render-mode.text:
${JSON.stringify([{t: "dynamicContainer", id: "ProductionScheduleTui",
                url: sri.buildUrl("../ProductionScheduleTui").addParameters({plantId: plantId || null, fromDay: fromDay || null,
                    days: days || null, scheduleChangeId: scheduleChangeId || null}).getUrlWithParams()}])}
